"""Static, editable application starters and system preview."""
from pathlib import Path
import json,html
R=Path(__file__).resolve().parent.parent
def generate():
 css=''
 for fam,file,weight in [('Archivo','archivo-400.ttf',400),('Archivo','archivo-600.ttf',600),('Archivo','archivo-700.ttf',700),('Besley','besley-400.ttf',400),('Besley','besley-600.ttf',600),('Courier Prime','CourierPrime-Regular.ttf',400)]:
  css+=f'@font-face{{font-family:"{fam}";src:url("../assets/fonts/{file}");font-weight:{weight};font-display:swap}}\n'
 css+='''
*{box-sizing:border-box}html{background:var(--cc-color-canvas);color:var(--cc-color-text)}body{margin:0;font:16px/1.5 Archivo,Arial,sans-serif}h1,h2,h3,p{margin-top:0}h1{font:600 clamp(40px,5vw,64px)/1.08 Besley,Georgia,serif;letter-spacing:-.02em;max-width:18ch}h2{font-size:32px;line-height:1.2}h3{font-size:24px;line-height:1.25}p{max-width:68ch}.wrap{max-width:1280px;margin:auto;padding:32px 48px}header{border-bottom:1px solid var(--cc-color-rule)}nav{display:flex;align-items:center;justify-content:space-between;gap:24px;flex-wrap:wrap}.logo{width:260px;height:auto}.logo.dark{display:none}:root[data-theme=dark] .logo.light{display:none}:root[data-theme=dark] .logo.dark{display:block}@media(prefers-color-scheme:dark){:root:not([data-theme]) .logo.light{display:none}:root:not([data-theme]) .logo.dark{display:block}}.meta{font:12px/1.5 'Courier Prime',monospace;letter-spacing:.04em;text-transform:uppercase;color:var(--cc-color-muted)}.kicker{color:var(--cc-color-action-text)}.hero{padding-top:64px;padding-bottom:64px}.lead{font:22px/1.5 Besley,Georgia,serif}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}.two{grid-template-columns:repeat(2,minmax(0,1fr))}.plate{border:1px solid var(--cc-color-rule);padding:24px;margin:24px 0}.panel{background:var(--cc-color-surface)}.rule{border-top:1px solid var(--cc-color-rule);padding-top:24px;margin-top:32px}.btn,button{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:44px;padding:10px 16px;border:1px solid var(--cc-color-action);border-radius:4px;background:var(--cc-color-action);color:var(--cc-color-on-action);font:600 14px/20px Archivo,sans-serif;cursor:pointer;text-decoration:none;transition:background var(--cc-motion-fast) var(--cc-motion-easing)}button:hover,.btn:hover{background:var(--cc-color-action-hover)}button:active,.btn:active{background:var(--cc-color-action-pressed)}.secondary{color:var(--cc-color-text);border-color:var(--cc-color-control-border);background:transparent}.secondary:hover{background:var(--cc-color-surface)}.danger{background:var(--cc-color-danger);color:var(--cc-color-on-danger);border-color:var(--cc-color-danger)}.danger:hover{background:var(--cc-color-danger-hover)}.danger:active{background:var(--cc-color-danger-pressed);box-shadow:inset 0 0 0 2px var(--cc-color-on-danger)}button:disabled{background:var(--cc-color-disabled);color:var(--cc-color-disabled-text);border-color:var(--cc-color-control-border);cursor:not-allowed}:focus-visible{outline:2px solid var(--cc-color-focus);outline-offset:3px}a{color:var(--cc-color-action-text);text-underline-offset:3px}label{display:block;font-weight:600;font-size:14px;margin-bottom:8px}input,select,textarea{max-width:100%;min-height:44px;padding:10px 12px;border:1px solid var(--cc-color-control-border);border-radius:4px;background:var(--cc-color-canvas);color:var(--cc-color-text);font:16px/24px Archivo,sans-serif}input::placeholder{color:var(--cc-color-muted);opacity:1}.field{margin:24px 0}.hint{font-size:14px;color:var(--cc-color-muted);margin-top:8px}.error{color:var(--cc-color-danger-text)}.row{display:flex;flex-wrap:wrap;gap:16px;align-items:center}.badge{font-size:14px;padding:4px 8px;border:1px solid currentColor;border-radius:2px}.success{color:var(--cc-color-success)}.warning{color:var(--cc-color-warning-text)}.alert{padding:20px 24px;border-left:3px solid var(--cc-color-warning);background:var(--cc-color-warning-surface);color:var(--cc-color-text)}table{width:100%;border-collapse:collapse;font-size:14px}th,td{padding:12px 16px;min-height:44px;border-bottom:1px solid var(--cc-color-rule);text-align:left}th{background:var(--cc-color-surface);font-weight:600}.numeric{text-align:right;font-variant-numeric:tabular-nums}.table-scroll{overflow:auto}caption{text-align:left;padding:16px 0;font-weight:600}.reading{max-width:760px}.reading p{font:18px/29px Besley,Georgia,serif}.source{font:12px/17px 'Courier Prime',monospace;color:var(--cc-color-muted)}.skip{position:absolute;top:-100px;left:24px;background:var(--cc-color-canvas);padding:16px;z-index:100}.skip:focus{top:12px}.template-note{font-size:14px;color:var(--cc-color-muted)}.footer{border-top:1px solid var(--cc-color-rule);margin-top:64px;padding-top:24px}.swatches{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.swatch{height:80px;border:1px solid var(--cc-color-rule)}.index{columns:2;column-gap:48px}.index li{margin-bottom:12px}.guide-section{padding:48px 0;border-bottom:1px solid var(--cc-color-rule)}.guide-section img{max-width:100%;height:auto}.guide-section h2{font-family:Besley,Georgia,serif}.guide-block{display:grid;grid-template-columns:220px 1fr;gap:32px;margin-top:32px}.guide-block h3{font-size:18px}.doc{max-width:900px}.doc h1{font-size:48px}.slide{aspect-ratio:16/9;padding:6%;border:1px solid var(--cc-color-rule);display:flex;flex-direction:column;justify-content:center;margin:32px 0}.slide h2{font:600 clamp(32px,4vw,64px)/1.12 Besley,serif;max-width:19ch}.social{max-width:1080px;aspect-ratio:1;padding:7%;border:1px solid var(--cc-color-rule);display:flex;flex-direction:column;justify-content:center}.social h1{font-size:clamp(40px,5vw,64px)}
@media(max-width:1199px){.wrap{padding-left:32px;padding-right:32px}.grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:767px){.wrap{padding-left:20px;padding-right:20px}.grid,.two{grid-template-columns:1fr}.hero{padding-top:40px;padding-bottom:40px}.guide-block{grid-template-columns:1fr;gap:8px}.index{columns:1}.logo{width:260px;max-width:100%}.swatches{grid-template-columns:repeat(2,1fr)}.slide{aspect-ratio:auto;min-height:320px}.doc h1{font-size:36px}}
@media print{html:root{--cc-color-canvas:#F4EFE2;--cc-color-surface:#EAE2CD;--cc-color-text:#1E1B16;--cc-color-muted:#5C554A;--cc-color-rule:#C9BFA8;--cc-color-action-text:#95450F;color-scheme:light}body{font-size:10.5pt;line-height:15pt;background:white;color:#1E1B16}.theme,.template-note,.skip{display:none}.wrap{padding:0;max-width:none}header{margin-bottom:24pt}.guide-section{break-before:page}.guide-block{break-inside:avoid}.logo.light{display:block!important}.logo.dark{display:none!important}h1,h2,h3{break-after:avoid}thead{display:table-header-group}tr{break-inside:avoid}a{color:inherit}.slide{break-after:page;margin:0;border:0}.slide:last-child{break-after:auto}@page{size:letter;margin:42pt}}
'''
 css+='\n'+(R/'source/application-refinements.css').read_text(encoding='utf-8')
 (R/'templates/styles.css').write_text(css,encoding='utf-8')
 js='''(()=>{const root=document.documentElement;let saved;try{saved=localStorage.getItem('cc-theme')}catch{}if(saved==='light'||saved==='dark')root.dataset.theme=saved;document.addEventListener('DOMContentLoaded',()=>{const el=document.getElementById('theme');if(!el)return;el.value=saved||'system';el.addEventListener('change',()=>{root.classList.add('theme-changing');const val=el.value;if(val==='system')delete root.dataset.theme;else root.dataset.theme=val;try{localStorage.setItem('cc-theme',val)}catch{}void root.offsetHeight;requestAnimationFrame(()=>root.classList.remove('theme-changing'))})})})();'''
 (R/'templates/theme.js').write_text(js,encoding='utf-8')
 def shell(title,body,root=False,extra=''):
  pre='templates/' if root else '';asset='' if root else '../'
  extra+='<link rel="icon" href="data:,">'
  return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | Cypress Command</title><script src="{pre}theme.js"></script><link rel="stylesheet" href="{asset}tokens/tokens.css"><link rel="stylesheet" href="{pre}styles.css">{extra}</head><body><a class="skip" href="#main">Skip to content</a><header><nav class="wrap" aria-label="Brand and appearance"><img class="logo light" src="{asset}assets/logos/cc-v1-horizontal-light.svg" alt="Cypress Command"><img class="logo dark" src="{asset}assets/logos/cc-v1-horizontal-dark.svg" alt="Cypress Command"><div class="theme"><label for="theme">Appearance</label><select id="theme"><option value="system">System</option><option value="light">Light</option><option value="dark">Dark</option></select></div></nav></header><main id="main" class="wrap">{body}<footer class="footer source">CYPRESS COMMAND / Practical systems. Smarter operations. / 1.1.1</footer></main></body></html>'''
 note='<p class="template-note">Editable layout starter. Bracketed content requires replacement. Sample controls are not connected to a service.</p>'
 templates={
 'website':'''<section class="hero"><p class="meta kicker">CORE EDITORIAL / [OFFER]</p><h1>Practical systems. Smarter operations.</h1><p class="lead">We design and implement AI, software, and workflows around how your business operates.</p><a class="btn" href="#approach">Explore the approach</a></section><section id="approach"><h2>A practical path forward</h2><div class="grid"><article class="plate"><p class="meta">01 / ASSESS</p><h3>Understand the work</h3><p>[Describe the assessment and its evidence.]</p></article><article class="plate"><p class="meta">02 / DESIGN</p><h3>Define the system</h3><p>[Describe a concrete deliverable.]</p></article><article class="plate"><p class="meta">03 / OPERATE</p><h3>Make it repeatable</h3><p>[Describe verification and ongoing ownership.]</p></article></div><section class="rule"><h2>Evidence</h2><p>[Add a verified case study, source and permission to publish.]</p></section><section class="rule"><h2>Next action</h2><p>[Add an authorized contact route or booking destination.]</p></section></section>''',
 'article':'''<article class="reading hero"><p class="meta kicker">ARCHIVAL INTELLIGENCE / FIELD NOTES</p><h1>Ideas that survive the next tool.</h1><p class="lead">[A concise thesis grounded in experience or cited research.]</p><p class="source">[Author] / [Publication date] / [Revision]</p><section class="rule"><h2>The observation</h2><p>[Describe what happened, why it matters and the limits of the evidence.]</p></section><section class="rule"><h2>The interpretation</h2><p>[Separate confirmed facts from judgment. Link the sources at the point of use.]</p><figure class="plate"><figcaption>Fig. 01 / [Descriptive figure title]</figcaption><p>[Insert a diagram with an accessible text equivalent.]</p><p class="source">Source: [source] / As of: [date]</p></figure></section><section class="rule"><h2>The practical implication</h2><p>[Give the reader a concrete application or next action.]</p></section><section class="rule"><h2>Notes and references</h2><ol><li>[Source, author, title, date and link]</li></ol></section></article>''',
 'report':'''<article class="doc hero"><p class="meta kicker">REPORT / [CLASSIFICATION]</p><h1>[Decision-focused report title]</h1><p class="lead">[Executive finding in one or two sentences.]</p><p class="source">Prepared for [audience] / By [author] / [date] / Revision [version]</p><section class="rule"><h2>01 / Scope and method</h2><p>[Question, evidence period, sources, exclusions and method.]</p></section><section class="rule"><h2>02 / Findings</h2><div class="table-scroll"><table><caption>Evidence register</caption><thead><tr><th>Finding</th><th>Evidence</th><th>Status</th></tr></thead><tbody><tr><td>[Finding]</td><td>[Source and date]</td><td>[Confirmed / assumption / unknown]</td></tr></tbody></table></div></section><section class="rule"><h2>03 / Recommendation</h2><p>[Recommended action, rationale, owner and timing.]</p></section><section class="rule"><h2>04 / Limitations and sources</h2><p>[Material gaps and complete source register.]</p></section></article>''',
 'proposal':'''<article class="doc hero"><p class="meta kicker">PROPOSAL / DRAFT / [CONFIDENTIALITY]</p><h1>[Outcome] for [client]</h1><p class="lead">[Specific problem and proposed result.]</p><p class="source">Prepared by [author] / [date] / Revision [version]</p><section class="rule"><h2>01 / Scope</h2><p>[Included work and deliverables.]</p><p>[Explicit exclusions and client dependencies.]</p></section><section class="rule"><h2>02 / Delivery approach</h2><p>[Phases, milestones, acceptance criteria and responsible parties.]</p></section><section class="rule"><h2>03 / Schedule and fees</h2><div class="table-scroll"><table><caption>Draft commercial schedule</caption><thead><tr><th>Deliverable</th><th>Timing</th><th class="numeric">Fee</th></tr></thead><tbody><tr><td>[Deliverable]</td><td>[Duration or date]</td><td class="numeric">[Currency and amount]</td></tr></tbody></table></div><p class="hint">[Pricing assumptions, expenses, payment terms and validity period.]</p></section><section class="rule"><h2>04 / Next action</h2><p>[Review or approval path. Draft; not evidence of an executed agreement.]</p></section></article>''',
 'sop':'''<article class="doc hero"><p class="meta kicker">TECHNICAL SYSTEMS / SOP [ID]</p><h1>[Procedure name]</h1><p class="source">Owner [name] / Effective [date] / Version [version]</p><section class="plate panel"><h2>Before you begin</h2><p>Trigger: [event]</p><p>Inputs and permissions: [requirements]</p><p>Expected result: [observable acceptance condition]</p></section><ol><li><h3>[Action verb + object]</h3><p>[Instructions, owner and expected evidence.]</p></li><li><h3>Verify [result]</h3><p>[Check and pass/fail criterion.]</p></li><li><h3>Record [outcome]</h3><p>[Location, retention rule and reviewer.]</p></li></ol><section class="alert"><h2>Exception path</h2><p>[Stop condition, escalation contact and recovery procedure.]</p></section><section class="rule"><h2>Revision history</h2><p>[Date, change, author, reviewer.]</p></section></article>''',
 'deck':'''<p class="meta kicker">PRESENTATION / 16:9 / EDITABLE LAYOUT</p><section class="slide"><p class="meta">[AUDIENCE] / [DATE]</p><h2>From complexity to clarity.</h2><p class="lead">[One-sentence proposition.]</p></section><section class="slide"><p class="meta">01 / THE PROBLEM</p><h2>[One decision-relevant finding]</h2><p class="lead">[One supporting evidence point.]</p><p class="source">[Source and date]</p></section><section class="slide"><p class="meta">02 / THE RECOMMENDATION</p><h2>[One specific action]</h2><p class="lead">[Owner, timing and success condition.]</p></section><section class="slide"><p class="meta">03 / THE DECISION</p><h2>[What needs approval]</h2><p class="lead">[Tradeoff, request and next step.]</p></section>''',
 'dashboard':'''<section class="hero"><p class="meta kicker">DIGITAL COMMAND / ILLUSTRATIVE LAYOUT</p><h1>Operational overview</h1><p class="source">Source: not connected / Last refresh: unavailable</p><div class="field"><label for="scope">Scope</label><select id="scope"><option>All records (sample)</option></select></div><div class="grid"><article class="plate"><h2>Measure A</h2><p class="lead">Unavailable</p><p class="hint">[Definition, units and period]</p></article><article class="plate"><h2>Measure B</h2><p class="lead">Unavailable</p><p class="hint">[Definition, units and period]</p></article><article class="plate"><h2>Measure C</h2><p class="lead">Unavailable</p><p class="hint">[Definition, units and period]</p></article></div><section class="alert"><h2>Connect a verified source</h2><p>No operating data is connected to this template.</p></section><div class="table-scroll" role="region" aria-label="Operational records" tabindex="0"><table><caption>Records / empty state</caption><thead><tr><th>Record</th><th>Status</th><th>Updated</th><th>Next action</th></tr></thead><tbody><tr><td colspan="4">No data source connected. Values are unavailable.</td></tr></tbody></table></div></section>''',
 'social':'''<p class="meta kicker">SOCIAL / SQUARE / EDITABLE LAYOUT</p><article class="social"><p class="meta kicker">FIELD NOTE / [NUMBER]</p><h1>[One useful idea, clearly stated.]</h1><p class="lead">[One supporting sentence, with evidence where needed.]</p><div class="rule"><p class="source">[Author] / [Source] / [Date]</p><p>Cypress Command</p></div></article><section class="rule"><h2>Companion post and alt text</h2><p>[Provide the full idea in plain text. Describe the meaningful visual content without repeating decorative elements.]</p></section>'''
 }
 templates['website']=templates['website'].replace('<article class="plate">','<article class="plate brand-olive">',1).replace('<article class="plate">','<article class="plate brand-mustard">',1).replace('<article class="plate">','<article class="plate brand-terra">',1).replace('<section class="rule"><h2>Evidence</h2>','<section class="color-feature brand-oxblood-strong"><h2>Evidence</h2>')
 templates['article']=templates['article'].replace('<figure class="plate">','<figure class="plate editorial-note">')
 templates['report']=templates['report'].replace('<section class="rule"><h2>03 / Recommendation</h2>','<section class="color-feature brand-olive"><h2>03 / Recommendation</h2>')
 templates['proposal']=templates['proposal'].replace('<section class="rule"><h2>01 / Scope</h2>','<section class="color-feature brand-terra"><h2>01 / Scope</h2>')
 templates['sop']=templates['sop'].replace('class="plate panel"','class="plate brand-olive"')
 templates['deck']=templates['deck'].replace('<section class="slide">','<section class="slide color-feature brand-oxblood-strong">',1).replace('<section class="slide">','<section class="slide color-feature brand-mustard">',1)
 templates['social']=templates['social'].replace('class="social"','class="social color-feature brand-olive-strong"')
 templates['dashboard']=templates['dashboard'].replace('<article class="plate">','<article class="plate brand-olive">',1).replace('<article class="plate">','<article class="plate brand-mustard">',1).replace('<article class="plate">','<article class="plate brand-terra">',1)
 for name,body in templates.items():
  if name=='website': body=(R/'source/website-body.html').read_text(encoding='utf-8-sig')
  extra='<style>@media print{@page{size:13.333in 7.5in;margin:0}.slide{height:7.5in}header,.meta.kicker,footer{display:none}}</style>' if name=='deck' else ''
  (R/f'templates/{name}.html').write_text(shell(name.title(),('' if name=='website' else note)+body,extra=extra+('<link rel="stylesheet" href="service-model.css">' if name=='website' else '')),encoding='utf-8')
 spec=json.loads((R/'source/specification.json').read_text())
 body='<section class="hero"><p class="meta kicker">SPECIFICATION / 1.1.1</p><h1>An editorial operating system for serious work.</h1><p class="lead">The complete editable guide, application starters and light/dark role preview.</p><p><a href="Cypress_Command_Design_System_v1.pdf">Open the PDF guide</a> · <a href="tokens/tokens.json">Token JSON</a></p></section><h2>Application starters</h2><ul class="index">'
 body+=''.join(f'<li><a href="templates/{name}.html">{name.title()}</a></li>' for name in templates)+'</ul>'
 body+='''<section class="guide-section"><h2>Component and theme preview</h2><div class="row"><button type="button">Primary example</button><button type="button" class="secondary">Secondary example</button><button type="button" class="danger">Danger example</button><button type="button" disabled>Unavailable</button></div><div class="field"><label for="example">Project name</label><input id="example" placeholder="Example project" aria-describedby="helper"><p id="helper" class="hint">Visible label and persistent helper text.</p></div><div class="row"><span class="badge success">✓ Verified</span><span class="badge warning">! Needs review</span><span class="badge error">× Failed</span></div><p class="template-note">Visual examples only; buttons do not submit data.</p></section>'''
 for p in spec['pages']:
  body+='<section class="guide-section"><p class="meta kicker">'+html.escape(p['kicker'])+'</p><h2>'+html.escape(p['title']).replace('\n',' ')+'</h2><p class="lead">'+html.escape(p['intro'])+'</p>'
  for title,text in p['blocks']:body+='<div class="guide-block"><h3>'+html.escape(title)+'</h3><p>'+html.escape(text).replace('\n','<br>')+'</p></div>'
  if p['kind']=='reference-board':body+='<img alt="Supplied '+('dark' if p['dark'] else 'light')+' master application board; illustrative design reference" src="references/master-application-board-'+('dark' if p['dark'] else 'light')+'.png">'
  if p['kind']=='contrast':body+='<p><a href="tokens/contrast-matrix.csv">Download the complete measured contrast matrix.</a></p>'
  body+='</section>'
 from portal import generate_portal
 generate_portal(shell,templates)
if __name__=='__main__':generate()
